import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import ts from 'typescript';
import prettier from 'prettier';

const root = fileURLToPath(new URL('../../', import.meta.url));
const header =
  '// Generated by tools/dev/agent-contracts.mjs from shared wire contracts. Do not edit.\n';

/** Package only the agent contract and the room limits it uses, never host dependencies. */
export async function agentContractArtifacts() {
  const agent = await readFile(path.join(root, 'packages/shared/src/types/Agent.ts'), 'utf8');
  const room = await readFile(
    path.join(root, 'packages/shared/src/types/RoomTransport.ts'),
    'utf8',
  );
  const tree = ts.createSourceFile('RoomTransport.ts', room, ts.ScriptTarget.Latest, true);
  const names = new Set(['GRID', 'MAX_STATUS_TEXT_LENGTH']);
  const limits = tree.statements.filter(
    statement =>
      ts.isVariableStatement(statement) &&
      statement.declarationList.declarations.some(declaration =>
        names.has(declaration.name.getText(tree)),
      ),
  );
  if (limits.length !== names.size)
    throw new Error('Missing canonical room limits for the agent contract');
  const source = `${limits.map(statement => statement.getText(tree)).join('\n')}\n${agent}`;
  const parsed = ts.createSourceFile('contracts.mts', source, ts.ScriptTarget.Latest, true);
  if (
    parsed.statements.some(
      statement =>
        ts.isImportDeclaration(statement) ||
        (ts.isExportDeclaration(statement) && statement.moduleSpecifier),
    )
  )
    throw new Error('The packaged agent wire contract must stay dependency-free');
  const options = { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext };
  const declarations = ts.transpileDeclaration(source, {
    fileName: 'contracts.mts',
    compilerOptions: options,
  });
  if (declarations.diagnostics?.length)
    throw new Error(
      ts.formatDiagnosticsWithColorAndContext(declarations.diagnostics, {
        getCurrentDirectory: () => root,
        getCanonicalFileName: name => name,
        getNewLine: () => '\n',
      }),
    );
  const implementation =
    header + ts.transpileModule(source, { compilerOptions: options }).outputText;
  const declarationPath = path.join(root, 'packages/scape-agent-mcp/contracts.d.mts');
  const prettierOptions = (await prettier.resolveConfig(declarationPath)) ?? {};
  const declaration = await prettier.format(header + declarations.outputText, {
    ...prettierOptions,
    parser: 'typescript',
    filepath: declarationPath,
  });
  return {
    'contracts.mjs': implementation,
    'contracts.d.mts': declaration,
  };
}

export async function generateAgentContracts(check = false) {
  for (const [name, content] of Object.entries(await agentContractArtifacts())) {
    const target = path.join(root, 'packages/scape-agent-mcp', name);
    if (check) {
      if ((await readFile(target, 'utf8')) !== content)
        throw new Error(
          `${name} is stale. Run yarn workspace @scape-wtf/agent-mcp generate:contracts.`,
        );
    } else await writeFile(target, content);
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.slice(2).some(arg => arg !== '--check'))
    throw new Error('Usage: agent-contracts.mjs [--check]');
  await generateAgentContracts(process.argv.includes('--check'));
}
